<script setup>import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import PrototypeBadge from '../components/PrototypeBadge.vue';import {webModules} from '../router/index.js';import {state,actions} from '../domain/prototypeStore.js';const route=useRoute(),collapsed=ref(false),title=computed(()=>route.meta.title||'应急管理'),roles=['应急指挥人员','值班人员','现场处置人员','物资管理员','系统管理员']</script>
<template><div class="web-shell" :class="{'is-collapsed':collapsed}"><aside class="sidebar"><div class="brand"><div class="brand-mark">应</div><div class="brand-copy"><strong>应急管理子系统</strong><small>智能运营中心</small></div></div><nav><RouterLink to="/web/dashboard" class="nav-item"><span>舱</span><b>应急驾驶舱</b></RouterLink><RouterLink v-for="x in webModules" :key="x.path" :to="`/web/${x.path}`" class="nav-item"><span>{{x.icon}}</span><b>{{x.title}}</b></RouterLink></nav></aside><section class="workspace"><header class="topbar"><button class="icon-button" @click="collapsed=!collapsed">☰</button><div><small>某自然博物馆</small><h1>{{title}}</h1></div><div class="topbar-actions"><PrototypeBadge/><select :value="state.user.role" @change="actions.switchRole($event.target.value)"><option v-for="r in roles" :key="r">{{r}}</option></select><details><summary class="surface-link">演示工具</summary><RouterLink to="/h5/home">切换移动端</RouterLink><button class="text-button" @click="actions.reset()">重置演示数据</button></details></div></header><main class="content"><RouterView/></main></section></div></template>
